interface Habit { id: number; name: string; days: string[] }
interface State { version: 2; habits: Habit[]; nextId: number }
interface StorageLike { getItem(key: string): string | null; setItem(key: string, value: string): void }

type Action =
  | { type: "add"; name: string }
  | { type: "rename"; id: number; name: string }
  | { type: "toggle"; id: number; day: string }
  | { type: "remove"; id: number };

const initialState: State = { version: 2, habits: [], nextId: 1 };
const KEY = "habits";
const DAY_MS = 24 * 60 * 60 * 1000;

function nameTaken(state: State, name: string, exceptId?: number): boolean {
  const lower = name.toLowerCase();
  return state.habits.some(h => h.id !== exceptId && h.name.toLowerCase() === lower);
}

function update(state: State, action: Action): State {
  switch (action.type) {
    case "add": {
      const name = action.name.trim();
      if (!name || nameTaken(state, name)) return state;
      return { ...state, habits: [...state.habits, { id: state.nextId, name, days: [] }], nextId: state.nextId + 1 };
    }
    case "rename": {
      const name = action.name.trim();
      const habit = state.habits.find(h => h.id === action.id);
      if (!habit || !name || name === habit.name || nameTaken(state, name, habit.id)) return state;
      return { ...state, habits: state.habits.map(h => (h.id === habit.id ? { ...h, name } : h)) };
    }
    case "toggle": {
      if (!state.habits.some(h => h.id === action.id)) return state;
      return {
        ...state,
        habits: state.habits.map(h => {
          if (h.id !== action.id) return h;
          const days = h.days.includes(action.day) ? h.days.filter(d => d !== action.day) : [...h.days, action.day].sort();
          return { ...h, days };
        }),
      };
    }
    case "remove": {
      if (!state.habits.some(h => h.id === action.id)) return state;
      return { ...state, habits: state.habits.filter(h => h.id !== action.id) };
    }
    default: {
      const unreachable: never = action;
      throw new Error(`unknown action ${JSON.stringify(unreachable)}`);
    }
  }
}

const toTime = (day: string): number => new Date(`${day}T00:00:00Z`).getTime();
const toDay = (time: number): string => new Date(time).toISOString().slice(0, 10);

function streak(days: readonly string[], today: string): number {
  const ticked = new Set(days);
  let t = toTime(today);
  if (!ticked.has(today)) t -= DAY_MS;
  let count = 0;
  while (ticked.has(toDay(t))) {
    count++;
    t -= DAY_MS;
  }
  return count;
}

function escapeHtml(text: string): string {
  return text.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;").replaceAll("'", "&#39;");
}

function render(state: State, today: string): string {
  if (state.habits.length === 0) return '<p class="empty">No habits yet.</p>';
  const rows = state.habits.map(h => {
    const name = escapeHtml(h.name);
    const n = streak(h.days, today);
    return `<li data-id="${h.id}"><button data-action="toggle" aria-pressed="${h.days.includes(today)}">${name}</button>` +
      `<span class="streak">${n} ${n === 1 ? "day" : "days"}</span>` +
      `<button data-action="remove" aria-label="Remove ${name}">×</button></li>`;
  });
  const done = state.habits.filter(h => h.days.includes(today)).length;
  return `<ul class="habits">${rows.join("")}</ul><p class="summary">${done} of ${state.habits.length} done today</p>`;
}

const isStringArray = (x: unknown): x is string[] => Array.isArray(x) && x.every(d => typeof d === "string");
const tidyDays = (days: string[]): string[] => [...new Set(days)].sort();

function isHabit(x: unknown): x is Habit {
  if (typeof x !== "object" || x === null) return false;
  const h = x as Record<string, unknown>;
  return typeof h.id === "number" && typeof h.name === "string" && isStringArray(h.days);
}

function fromStored(data: unknown): State {
  if (typeof data !== "object" || data === null) return initialState;
  const d = data as Record<string, unknown>;
  if (d.version === 2) {
    if (!Array.isArray(d.habits) || !d.habits.every(isHabit) || typeof d.nextId !== "number") return initialState;
    return { version: 2, habits: d.habits.map(h => ({ id: h.id, name: h.name, days: tidyDays(h.days) })), nextId: d.nextId };
  }
  if (d.version === 1) {
    if (!Array.isArray(d.habits)) return initialState;
    const habits: Habit[] = [];
    for (const old of d.habits as unknown[]) {
      const o = (typeof old === "object" && old !== null ? old : {}) as Record<string, unknown>;
      if (typeof o.name !== "string" || !isStringArray(o.done)) return initialState;
      habits.push({ id: habits.length + 1, name: o.name, days: tidyDays(o.done) });
    }
    return { version: 2, habits, nextId: habits.length + 1 };
  }
  return initialState;
}

function load(storage: StorageLike): State {
  try {
    const text = storage.getItem(KEY);
    return text === null ? initialState : fromStored(JSON.parse(text));
  } catch {
    return initialState;
  }
}

function save(storage: StorageLike, state: State): boolean {
  try {
    storage.setItem(KEY, JSON.stringify(state));
    return true;
  } catch {
    return false;
  }
}

unitTests:
const run = (...actions: Action[]): State => actions.reduce(update, initialState);

function fakeStorage(initial: Record<string, string> = {}, opts: { full?: boolean; broken?: boolean } = {}) {
  const data = new Map(Object.entries(initial));
  return {
    data,
    getItem(k: string) { if (opts.broken) throw new Error("blocked"); return data.get(k) ?? null; },
    setItem(k: string, v: string) { if (opts.full) throw new Error("full"); data.set(k, v); },
  };
}

test("adding and naming", () => {
  const s = run({ type: "add", name: "  Read " }, { type: "add", name: "Walk" });
  checkEq(s, { version: 2, habits: [{ id: 1, name: "Read", days: [] }, { id: 2, name: "Walk", days: [] }], nextId: 3 });
  check(update(s, { type: "add", name: "read" }) === s, "a duplicate name changes nothing");
  check(update(s, { type: "add", name: "   " }) === s, "an empty name changes nothing");
  checkEq(update(s, { type: "rename", id: 2, name: "Run" }).habits[1].name, "Run");
  check(update(s, { type: "rename", id: 2, name: "READ" }) === s, "renaming onto another habit's name");
  check(update(s, { type: "rename", id: 9, name: "X" }) === s, "unknown id");
  checkEq(update(s, { type: "rename", id: 1, name: "READ" }).habits[0].name, "READ");
  checkEq(initialState, { version: 2, habits: [], nextId: 1 });
});

test("toggling and removing", () => {
  const s = run({ type: "add", name: "Read" },
    { type: "toggle", id: 1, day: "2026-03-05" }, { type: "toggle", id: 1, day: "2026-03-03" }, { type: "toggle", id: 1, day: "2026-03-04" });
  checkEq(s.habits[0].days, ["2026-03-03", "2026-03-04", "2026-03-05"]);
  checkEq(update(s, { type: "toggle", id: 1, day: "2026-03-04" }).habits[0].days, ["2026-03-03", "2026-03-05"]);
  check(update(s, { type: "toggle", id: 7, day: "2026-03-04" }) === s, "unknown id");
  checkEq(update(s, { type: "remove", id: 1 }).habits, []);
  check(update(s, { type: "remove", id: 2 }) === s, "unknown id");
  checkEq(update(s, { type: "remove", id: 1 }).nextId, 2);
});

test("update does not change its input", () => {
  const s = run({ type: "add", name: "Read" }, { type: "toggle", id: 1, day: "2026-01-01" });
  const before = JSON.stringify(s);
  update(s, { type: "toggle", id: 1, day: "2026-01-02" });
  update(s, { type: "add", name: "Walk" });
  update(s, { type: "remove", id: 1 });
  checkEq(JSON.stringify(s), before);
});

test("streaks", () => {
  const days = ["2026-02-27", "2026-02-28", "2026-03-01", "2026-03-02"];
  checkEq(streak(days, "2026-03-02"), 4);
  checkEq(streak(days, "2026-03-03"), 4);
  checkEq(streak(days, "2026-03-04"), 0);
  checkEq(streak(["2025-12-31", "2026-01-01"], "2026-01-01"), 2);
  checkEq(streak(["2024-02-28", "2024-02-29", "2024-03-01"], "2024-03-01"), 3);
  checkEq(streak([], "2026-01-01"), 0);
});

test("rendering", () => {
  checkEq(render(initialState, "2026-03-02"), '<p class="empty">No habits yet.</p>');
  const s = run({ type: "add", name: "Read <books>" }, { type: "add", name: "Walk" },
    { type: "toggle", id: 1, day: "2026-03-01" }, { type: "toggle", id: 1, day: "2026-03-02" },
    { type: "toggle", id: 2, day: "2026-03-01" });
  checkEq(render(s, "2026-03-02"),
    '<ul class="habits">' +
    '<li data-id="1"><button data-action="toggle" aria-pressed="true">Read &lt;books&gt;</button><span class="streak">2 days</span><button data-action="remove" aria-label="Remove Read &lt;books&gt;">×</button></li>' +
    '<li data-id="2"><button data-action="toggle" aria-pressed="false">Walk</button><span class="streak">1 day</span><button data-action="remove" aria-label="Remove Walk">×</button></li>' +
    '</ul><p class="summary">1 of 2 done today</p>');
});

test("saving and loading", () => {
  const storage = fakeStorage();
  const s = run({ type: "add", name: "Read" }, { type: "toggle", id: 1, day: "2026-03-01" });
  checkEq(save(storage, s), true);
  checkEq(load(storage), s);
  checkEq(save(fakeStorage({}, { full: true }), s), false);
  checkEq(load(fakeStorage({ habits: '{"version": 2, "habits": [{"id": 4, "name": "A", "days": ["2026-01-02", "2026-01-01", "2026-01-02"]}], "nextId": 5}' })),
    { version: 2, habits: [{ id: 4, name: "A", days: ["2026-01-01", "2026-01-02"] }], nextId: 5 });
});

test("migrating version 1", () => {
  const old = '{"version": 1, "habits": [{"name": "Read", "done": ["2026-01-02", "2026-01-01"]}, {"name": "Walk", "done": []}]}';
  checkEq(load(fakeStorage({ habits: old })), {
    version: 2,
    habits: [{ id: 1, name: "Read", days: ["2026-01-01", "2026-01-02"] }, { id: 2, name: "Walk", days: [] }],
    nextId: 3,
  });
});

test("bad stored data", () => {
  const bad = ["{oops", "null", "[]", '{"version": 3}', '{"version": 2, "habits": [{"id": "1", "name": "A", "days": []}], "nextId": 2}',
    '{"version": 2, "habits": [], "nextId": "2"}', '{"version": 1, "habits": [{"name": "A", "done": [1]}]}'];
  for (const text of bad) checkEq(load(fakeStorage({ habits: text })), initialState);
  checkEq(load(fakeStorage()), initialState);
  checkEq(load(fakeStorage({}, { broken: true })), initialState);
});

